SELECT  FROM stk_fund_nav
WHERE fund_code = #{fundCode}
AND nav_date BETWEEN #{startDate} AND #{endDate}
ORDER BY nav_date

SELECT  FROM stk_fund_nav
WHERE fund_code = #{fundCode}
ORDER BY nav_date DESC LIMIT #{limit}

SELECT  FROM stk_fund_nav
WHERE fund_code = #{fundCode}
ORDER BY nav_date DESC LIMIT 1
